using sv_d97d2dae2f2747e4b67a413e35d90e14.Client.Services;

namespace sv_d97d2dae2f2747e4b67a413e35d90e14.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTime(2026, 7, 2),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "New York, NY", Timestamp = new DateTime(2026, 6, 24, 9, 0, 0) },
                new StatusUpdate { Description = "Arrived at sorting facility", Location = "Philadelphia, PA", Timestamp = new DateTime(2026, 6, 25, 3, 30, 0) },
                new StatusUpdate { Description = "In transit to next facility", Location = "Chicago, IL", Timestamp = new DateTime(2026, 6, 26, 14, 15, 0) },
            ]
        },
        ["TRK-002"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTime(2026, 6, 25),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Seattle, WA", Timestamp = new DateTime(2026, 6, 22, 10, 0, 0) },
                new StatusUpdate { Description = "Arrived at distribution center", Location = "Portland, OR", Timestamp = new DateTime(2026, 6, 23, 6, 45, 0) },
                new StatusUpdate { Description = "Out for delivery", Location = "San Francisco, CA", Timestamp = new DateTime(2026, 6, 25, 8, 0, 0) },
                new StatusUpdate { Description = "Delivered", Location = "San Francisco, CA", Timestamp = new DateTime(2026, 6, 25, 14, 22, 0) },
            ]
        },
        ["TRK-003"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = new DateTime(2026, 7, 5),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Label created", Location = "Dallas, TX", Timestamp = new DateTime(2026, 6, 26, 16, 0, 0) },
                new StatusUpdate { Description = "Awaiting carrier pickup", Location = "Dallas, TX", Timestamp = new DateTime(2026, 6, 27, 8, 0, 0) },
            ]
        }
    };

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment '{trackingNumber}' not found.");
    }
}

